package com.example.amanafarm_backend;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.*;
import org.springframework.mock.web.MockMultipartFile;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
class MarketplaceIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;
 private static final AtomicInteger serial=new AtomicInteger(1000000);
 private record Account(long id,String email,String phone,String token){}
 private Account owner,other;
 @BeforeEach void accounts()throws Exception{owner=register();other=register();}
 private Account register()throws Exception{String phone="5"+serial.getAndIncrement();String email="member"+phone+"@example.test";var body=Map.of("firstName","Ahmed","lastName","Test","email",email,"phone",phone,"password","Password123!");var result=mvc.perform(post("/api/auth/register").contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isOk()).andReturn();var data=json.readTree(result.getResponse().getContentAsString());return new Account(data.get("id").asLong(),email,phone,data.get("token").asText());}
 private Map<String,Object> animal(){return new HashMap<>(Map.of("title","Annonce mouton","description","Description reelle pour le test","category","أغنام","price",450,"wilaya","تونس","phone",owner.phone(),"images",List.of()));}
 private Map<String,Object> product(){return new HashMap<>(Map.of("title","Aliment agricole","description","Description reelle du produit","category","علف","price",30,"wilaya","نابل","location","نابل","contactPhone",owner.phone(),"imageUrl","","inStock",true));}
 private JsonNode create(String path,Map<String,Object> body)throws Exception{return json.readTree(mvc.perform(post(path).header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 @Test void unauthenticatedWritesAndPrivateListsRequireLogin()throws Exception{mvc.perform(post("/api/animals").contentType("application/json").content(json.writeValueAsString(animal()))).andExpect(status().isUnauthorized());mvc.perform(get("/api/favorites")).andExpect(status().isUnauthorized());mvc.perform(get("/api/users/me").header("Authorization","Bearer invalid")).andExpect(status().isUnauthorized());}
 @Test void animalLifecycleIsPersistentAndOwnerOnly()throws Exception{
  var request=animal();request.put("userId",other.id());request.put("trustedSeller",true);var a=create("/api/animals",request);long id=a.get("id").asLong();assertEquals(owner.id(),a.get("userId").asLong());assertFalse(a.get("trustedSeller").asBoolean());
  request.put("title","Annonce modifiee");mvc.perform(put("/api/animals/"+id).header("Authorization","Bearer "+other.token()).contentType("application/json").content(json.writeValueAsString(request))).andExpect(status().isForbidden());
  mvc.perform(put("/api/animals/"+id).header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.title").value("Annonce modifiee"));
  mvc.perform(delete("/api/animals/"+id).header("Authorization","Bearer "+other.token())).andExpect(status().isForbidden());mvc.perform(delete("/api/animals/"+id).header("Authorization","Bearer "+owner.token())).andExpect(status().isOk());mvc.perform(get("/api/animals/"+id)).andExpect(status().isNotFound());
 }
 @Test void invalidPublishingDataNeverCreatesAnOffer()throws Exception{var request=animal();request.put("title","x");request.put("price",-1);request.put("phone","123");mvc.perform(post("/api/animals").header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(request))).andExpect(status().isBadRequest());}
 @Test void productOwnershipAndVerificationComeFromServer()throws Exception{var request=product();request.put("userId",other.id());request.put("companyVerified",true);request.put("sellerVerified",true);var p=create("/api/products",request);assertEquals(owner.id(),p.get("userId").asLong());assertFalse(p.get("companyVerified").asBoolean());assertFalse(p.get("sellerVerified").asBoolean());long id=p.get("id").asLong();mvc.perform(delete("/api/products/"+id).header("Authorization","Bearer "+other.token())).andExpect(status().isForbidden());mvc.perform(delete("/api/products/"+id).header("Authorization","Bearer "+owner.token())).andExpect(status().isOk());mvc.perform(get("/api/products/"+id)).andExpect(status().isNotFound());}
 @Test void favoritesArePersistentPrivateAndIdempotent()throws Exception{long id=create("/api/animals",animal()).get("id").asLong();String body=json.writeValueAsString(Map.of("kind","animals","listingId",id));for(int i=0;i<2;i++)mvc.perform(post("/api/favorites").header("Authorization","Bearer "+owner.token()).contentType("application/json").content(body)).andExpect(status().isOk());mvc.perform(get("/api/favorites").header("Authorization","Bearer "+owner.token())).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(1));mvc.perform(get("/api/favorites").header("Authorization","Bearer "+other.token())).andExpect(jsonPath("$.length()").value(0));mvc.perform(delete("/api/favorites/animals/"+id).header("Authorization","Bearer "+owner.token())).andExpect(status().isNoContent());mvc.perform(get("/api/favorites").header("Authorization","Bearer "+owner.token())).andExpect(jsonPath("$.length()").value(0));}
 @Test void favoritesRejectMissingListings()throws Exception{mvc.perform(post("/api/favorites").header("Authorization","Bearer "+owner.token()).contentType("application/json").content("{\"kind\":\"animals\",\"listingId\":99999999}")).andExpect(status().isNotFound());}
 @Test void photosUploadAndCanBeReadFromTheConfiguredDirectory()throws Exception{byte[] bytes=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jYxkAAAAASUVORK5CYII=");var file=new MockMultipartFile("files","photo.png","image/png",bytes);var result=mvc.perform(multipart("/api/media").file(file).header("Authorization","Bearer "+owner.token())).andExpect(status().isOk()).andReturn();String url=json.readTree(result.getResponse().getContentAsString()).get("urls").get(0).asText();mvc.perform(get(url)).andExpect(status().isOk()).andExpect(content().bytes(bytes));}
 @Test void spoofedAndOversizedPhotosAreRejected()throws Exception{var fake=new MockMultipartFile("files","photo.png","image/png","not an image".getBytes());mvc.perform(multipart("/api/media").file(fake).header("Authorization","Bearer "+owner.token())).andExpect(status().isBadRequest());var huge=new MockMultipartFile("files","photo.jpg","image/jpeg",new byte[5*1024*1024+1]);mvc.perform(multipart("/api/media").file(huge).header("Authorization","Bearer "+owner.token())).andExpect(status().isBadRequest());}
 @Test void dangerousImageUrlsAreRejected()throws Exception{var request=product();request.put("imageUrl","javascript:alert(1)");mvc.perform(post("/api/products").header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(request))).andExpect(status().isBadRequest());}
 @Test void profileChangesAreRealAndDuplicatePhonesAreRejected()throws Exception{var body=Map.of("firstName","Nouveau","lastName","Nom","phone",owner.phone(),"role","ADMIN");mvc.perform(put("/api/users/me").header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isOk()).andExpect(jsonPath("$.fullName").value("Nouveau Nom")).andExpect(jsonPath("$.role").value("BUYER"));mvc.perform(get("/api/users/me").header("Authorization","Bearer "+owner.token())).andExpect(jsonPath("$.firstName").value("Nouveau"));mvc.perform(put("/api/users/me").header("Authorization","Bearer "+owner.token()).contentType("application/json").content(json.writeValueAsString(Map.of("firstName","Autre","lastName","Nom","phone",other.phone())))).andExpect(status().isConflict());}
 @Test void passwordChangeChecksTheCurrentPasswordAndUpdatesLogin()throws Exception{mvc.perform(put("/api/users/me/password").header("Authorization","Bearer "+owner.token()).contentType("application/json").content("{\"currentPassword\":\"wrong\",\"newPassword\":\"NewPassword123!\"}")).andExpect(status().isBadRequest());mvc.perform(put("/api/users/me/password").header("Authorization","Bearer "+owner.token()).contentType("application/json").content("{\"currentPassword\":\"Password123!\",\"newPassword\":\"NewPassword123!\"}")).andExpect(status().isOk());mvc.perform(post("/api/auth/login").contentType("application/json").content(json.writeValueAsString(Map.of("email",owner.email(),"password","Password123!")))).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").contentType("application/json").content(json.writeValueAsString(Map.of("email",owner.email(),"password","NewPassword123!")))).andExpect(status().isOk());}
 @Test void wholesaleServiceAndJobPublishingAssignsOwners()throws Exception{
  var bulk=new HashMap<String,Object>(Map.of("title","Lot de produits","description","Description complete du lot","category","معدات","price",300,"location","تونس","contactPhone",owner.phone(),"minQuantity",3));var w=create("/api/wholesale",bulk);assertEquals(owner.id(),w.get("userId").asLong());
  var worker=new HashMap<String,Object>(Map.of("name","Ahmed","title","Service agricole","description","Description complete du service","category","عامل فلاحي","price",50,"location","تونس","phone",owner.phone()));var service=create("/api/workers",worker);assertEquals(owner.id(),service.get("userId").asLong());mvc.perform(delete("/api/workers/"+service.get("id").asLong()).header("Authorization","Bearer "+other.token())).andExpect(status().isForbidden());
  var job=new HashMap<String,Object>(Map.of("title","Offre agricole","description","Description complete du poste","salary","1200","location","تونس","phone",owner.phone(),"employer","Ferme"));var j=create("/api/jobs",job);assertEquals(owner.id(),j.get("userId").asLong());mvc.perform(delete("/api/jobs/"+j.get("id").asLong()).header("Authorization","Bearer "+other.token())).andExpect(status().isForbidden());
 }
}
